import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/GET-DATA-_002fTYPE_003dGNM_002fODS.md","filePath":"manual-en/GET-DATA-_002fTYPE_003dGNM_002fODS.md","lastUpdated":1785684581000}'),n={name:"manual-en/GET-DATA-_002fTYPE_003dGNM_002fODS.md"};function r(i,e,d,h,c,m){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h4 id="_9-4-1-spreadsheet-files" tabindex="-1">9.4.1 Spreadsheet Files <a class="header-anchor" href="#_9-4-1-spreadsheet-files" aria-label="Permalink to &quot;9.4.1 Spreadsheet Files&quot;">​</a></h4><pre><code>GET DATA /TYPE={GNM, ODS}
        /FILE={’file_name’}
        /SHEET={NAME ’sheet_name’, INDEX n}
        /CELLRANGE={RANGE ’range’, FULL}
        /READNAMES={ON, OFF}
        /ASSUMEDSTRWIDTH=n.
</code></pre><p>Gnumeric spreadsheets (<a href="http://gnumeric.org" target="_blank" rel="noreferrer">http://gnumeric.org</a>), and spreadsheets in OpenDocument format (<a href="http://libreplanet.org/wiki/Group:OpenDocument/Software" target="_blank" rel="noreferrer">http://libreplanet.org/wiki/Group:OpenDocument/Software</a>) can be read using the <code>GET DATA</code> command. Use the <code>TYPE</code> subcommand to indicate the file’s format. /TYPE=GNM indicates Gnumeric files, /TYPE=ODS indicates OpenDocument. The <code>FILE</code> subcommand is mandatory. Use it to specify the name file to be read. All other subcommands are optional.</p><p>The format of each variable is determined by the format of the spreadsheet cell containing the first datum for the variable. If this cell is of string (text) format, then the width of the variable is determined from the length of the string it contains, unless the <code>ASSUMEDSTRWIDTH</code> subcommand is given.</p><p>The <code>SHEET</code> subcommand specifies the sheet within the spreadsheet file to read. There are two forms of the <code>SHEET</code> subcommand. In the first form, <code>/SHEET=name sheet_name</code>, the string sheet_name is the name of the sheet to read. In the second form, <code>/SHEET=index idx</code>, idx is a integer which is the index of the sheet to read. The first sheet has the index 1. If the <code>SHEET</code> subcommand is omitted, then the command reads the first sheet in the file.</p><p>The <code>CELLRANGE</code> subcommand specifies the range of cells within the sheet to read. If the subcommand is given as <code>/CELLRANGE=FULL</code>, then the entire sheet is read. To read only part of a sheet, use the form <code>/CELLRANGE=range &#39;top_left_cell:bottom_right_cell&#39;</code>. For example, the subcommand <code>/CELLRANGE=range &#39;C3:P19&#39;</code> reads columns C–P, and rows 3–19 inclusive. If no <code>CELLRANGE</code> subcommand is given, then the entire sheet is read.</p><p>If <code>/READNAMES=ON</code> is specified, then the contents of cells of the first row are used as the names of the variables in which to store the data from subsequent rows. This is the default. If <code>/READNAMES=OFF</code> is used, then the variables receive automatically assigned names.</p><p>The <code>ASSUMEDSTRWIDTH</code> subcommand specifies the maximum width of string variables read from the file. If omitted, the default value is determined from the length of the string in the first spreadsheet cell for each variable.</p>`,8)])])}const p=t(n,[["render",r]]);export{l as __pageData,p as default};
